45	    /**
46	     * Derives the owner's salutation at read time: the stored {@code title} followed by a single
47	     * space and the {@code lastName} when a title was supplied, otherwise just the {@code lastName}.
48	     */
49	    default String salutation(Owner owner) {
50	        String title = owner.getTitle();
51	        if (title == null || title.isBlank()) {
52	            return owner.getLastName();
53	        }
54	        return title + " " + owner.getLastName();
