57	    /**
58	     * Derives the owner's preferred contact channel at read time: {@code EMAIL} when an email is
59	     * present, otherwise {@code PHONE}.
60	     */
61	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
62	        return hasEmail(owner) ? OwnerDto.ContactPreferenceEnum.EMAIL
63	            : OwnerDto.ContactPreferenceEnum.PHONE;
64	    }
