66	    /**
67	     * Derives the owner's age band at read time from {@code birthDate}, computed against
68	     * {@code registrationDate} (falling back to the current date when none is stored):
69	     * {@code MINOR} when under 18, {@code ADULT} when 18-64, {@code SENIOR} when 65 or older.
70	     * Returns {@code null} when no birth date was supplied, so the field is absent for owners
71	     * created without one.
72	     */
73	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
74	        java.time.LocalDate birthDate = owner.getBirthDate();
75	        if (birthDate == null) {
76	            return null;
77	        }
78	        java.time.LocalDate asOf = owner.getRegistrationDate() != null
79	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
80	        int age = java.time.Period.between(birthDate, asOf).getYears();
81	        if (age < 18) {
82	            return OwnerDto.AgeBandEnum.MINOR;
83	        }
84	        if (age < 65) {
85	            return OwnerDto.AgeBandEnum.ADULT;
86	        }
87	        return OwnerDto.AgeBandEnum.SENIOR;
88	    }
