144	    /**
145	     * Derives the owner's membership points: starts at 0, adds 2 when an email is present, adds 1
146	     * when the owner had no namesakes at creation ({@code namesakeCount == 0}), adds 2 when the
147	     * owner belongs to a household of 3 or more members ({@code householdSize >= 3}, counted at
148	     * creation by {@code AssignHouseholdSize}), and adds 3 when the owner's tenure is at least one
149	     * elapsed fiscal year (fiscal years start 1 July) since its {@code registrationDate}.
150	     */
151	    default int membershipPoints(Owner owner) {
152	        int points = 0;
153	        if (hasEmail(owner)) {
154	            points += 2;
155	        }
156	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
157	            points += 1;
158	        }
159	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
160	            points += 2;
161	        }
162	        if (tenureFiscalYears(owner) >= 1) {
163	            points += 3;
164	        }
165	        return points;
166	    }
167	
168	    /**
169	     * Maps the owner's {@link #membershipPoints(Owner) membership points} to a numeric level:
170	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more, then applies the
171	     * household level ceiling (see {@link #uncappedMembershipLevel(Owner)}).
172	     *
173	     * <p>When a {@code membershipLevelCap} was recorded at creation time (by
174	     * {@code CapMembershipLevel}, as one above the maximum level among the owner's existing
175	     * household members), the level is clamped down to that cap. With no cap stored (no existing
176	     * household member when the owner was created) the uncapped level is returned unchanged.
177	     */
178	    default int membershipLevel(Owner owner) {
179	        int level = uncappedMembershipLevel(owner);
180	        Integer cap = owner.getMembershipLevelCap();
181	        if (cap != null && level > cap) {
182	            return cap;
183	        }
184	        return level;
185	    }
186	
187	    /**
188	     * The owner's membership level derived purely from its {@link #membershipPoints(Owner) points},
189	     * before the household level ceiling is applied: level 1 for 0-1 points, 2 for 2-3, 3 for 4-5,
190	     * and 4 for 6 or more.
191	     */
192	    default int uncappedMembershipLevel(Owner owner) {
193	        int points = membershipPoints(owner);
194	        if (points <= 1) {
195	            return 1;
196	        }
197	        if (points <= 3) {
198	            return 2;
199	        }
200	        if (points <= 5) {
201	            return 3;
202	        }
203	        return 4;
204	    }
